@Entity @Table(name="dms_dealers",uniqueConstraints=@UniqueConstraint(columnNames={"organizationCode","dealerCode"})) class DealerPartner{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=50)String dealerCode;@Column(nullable=false,length=140)String name;@Column(nullable=false,length=40)String taxNo;@Column(nullable=false,length=20)String status="DRAFT";double creditLimit;double creditUsed;@Column(nullable=false,length=20)String riskLevel="NORMAL";LocalDate agreementEnd;LocalDateTime createdAt;/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
protected DealerPartner(){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       */
DealerPartner(String o,String c,String n,String t,LocalDate e){organizationCode=o;dealerCode=c;name=n;taxNo=t;agreementEnd=e;createdAt=LocalDateTime.now();}}
