@Entity @Table(name="dms_channel_orders",uniqueConstraints=@UniqueConstraint(columnNames="orderNo")) class ChannelOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false)Long dealerId;@Column(nullable=false,length=50)String orderNo;@Column(nullable=false,length=50)String productCode;@Column(nullable=false,length=50)String regionCode;int quantity;double unitPrice;double totalAmount;@Column(nullable=false,length=20)String status="PENDING_APPROVAL";LocalDate orderDate;LocalDateTime createdAt;/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       */
protected ChannelOrder(){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 */
ChannelOrder(Long d,String n,String p,String r,int q,double u,LocalDate date){dealerId=d;orderNo=n;productCode=p;regionCode=r;quantity=q;unitPrice=u;totalAmount=q*u;orderDate=date;createdAt=LocalDateTime.now();}}
